def even_odd_count(num):
    even_count = 0
    odd_count = 0
    # Use abs() to handle negative numbers and convert to string to iterate over digits
    for char in str(abs(num)):
        digit = int(char)
        if digit % 2 == 0:
            even_count += 1
        else:
            odd_count += 1
    return (even_count, odd_count)
```

