import math

def triangle_area(a, b, c):
    # 檢查是否為有效的三角形
    if a + b > c and a + c > b and b + c > a:
        # 使用海倫公式 (Heron's formula) 計算面積
        s = (a + b + c) / 2
        area = math.sqrt(s * (s - a) * (s - b) * (s - c))
        return round(area, 2)
    else:
        return -1
```

