def encrypt(s):
    result = ""
    for char in s:
        if 'a' <= char <= 'z':
            # Shift by 4 (2 * 2)
            result += chr((ord(char) - ord('a') + 4) % 26 + ord('a'))
        elif 'A' <= char <= 'Z':
            result += chr((ord(char) - ord('A') + 4) % 26 + ord('A'))
        else:
            result += char
    return result
```

